package mz.uem.restaurante.service;
import mz.uem.restaurante.dao.StockDAO; import mz.uem.restaurante.model.*; import java.sql.SQLException; import java.util.*;
public class StockService { private StockDAO dao; private final List<ItemStock> temporario=new ArrayList<>(); private int sequencia=1;
 public void activarBaseDados(StockDAO d){dao=d;} public boolean isPersistente(){return dao!=null;}
 public List<ItemStock> listar(String filtro){try{if(dao!=null)return dao.listar(filtro);}catch(SQLException e){throw new IllegalStateException("Erro ao consultar stock: "+e.getMessage(),e);}String f=filtro==null?"":filtro.toLowerCase();return temporario.stream().filter(x->x.getNome().toLowerCase().contains(f)||x.getCategoria().toLowerCase().contains(f)).toList();}
 public ItemStock guardar(ItemStock x){validar(x);try{if(dao!=null)return dao.guardar(x);}catch(SQLException e){throw new IllegalStateException("Erro ao guardar stock: "+e.getMessage(),e);}if(x.getId()<=0){x.setId(sequencia++);temporario.add(x);}else{temporario.removeIf(a->a.getId()==x.getId());temporario.add(x);}return x;}
 public void eliminar(int id){try{if(dao!=null){dao.eliminar(id);return;}}catch(SQLException e){throw new IllegalStateException("Erro ao eliminar item: "+e.getMessage(),e);}temporario.removeIf(x->x.getId()==id);}
 public void movimentar(int id,double q,boolean entrada,String motivo,String utilizador){if(q<=0)throw new IllegalArgumentException("A quantidade deve ser maior que zero.");try{if(dao!=null){dao.movimentar(id,q,entrada,motivo,utilizador);return;}}catch(SQLException e){throw new IllegalStateException("Erro no movimento de stock: "+e.getMessage(),e);}ItemStock x=temporario.stream().filter(a->a.getId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("Item não encontrado."));double novo=entrada?x.getQuantidade()+q:x.getQuantidade()-q;if(novo<0)throw new IllegalArgumentException("Stock insuficiente.");x.setQuantidade(novo);}
 public List<MovimentoStock> listarMovimentos(){try{if(dao!=null)return dao.listarMovimentos(200);}catch(SQLException e){throw new IllegalStateException("Erro ao consultar movimentos: "+e.getMessage(),e);}return List.of();}
 private void validar(ItemStock x){if(x.getNome()==null||x.getNome().isBlank()||x.getCategoria()==null||x.getCategoria().isBlank()||x.getUnidade()==null||x.getUnidade().isBlank())throw new IllegalArgumentException("Preencha nome, categoria e unidade.");if(x.getQuantidade()<0||x.getStockMinimo()<0)throw new IllegalArgumentException("Quantidade e stock mínimo não podem ser negativos.");}
}
